CSP-S2020题目整理 T1 儒略日 这道题目在考场上卡爆我 然后我就废了 这道题实际上就是考察一个对于闰年和平年的研究 我们可以先预处理前四百年的情况，然后对于在1582年之前的和1582年之后的分类讨论一下，然后这样就可以直接加减了 用一个函数来返回月份的天数似乎比较方便 参考代码 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int long long using namespace std; const int maxn= 146097 ; int q; int y[maxn],m[maxn],d[maxn]; int r,tmp; int calc ( int year, int month) { if (month== 2 ) { if (year% 4 != 0 ) return 28 ; else { if (year% 100 != 0 ) return 29 ; else { if (year% 400 != 0 ) return 28 ; else return 29 ; } } } if (month== 4 ||month== 6 ||month== 9 ||month== 11 ) return 30 ; else return 31 ; } signed main () { m[ 0 ]=d[ 0 ]= 1 ; for ( int i= 1 ;i<maxn;i++) { d[i]=d[i -1 ] +1 ; m[i]=m[i -1 ]; y[i]=y[i -1 ]; if (d[i]> calc (y[i],m[i])) { m[i]++,d[i]= 1 ; } if (m[i]> 12 ) { y[i]++; m[i]= 1 ; } } cin>>q; while (q--) { cin>>r; if (r> 2299160 ) { r-= 2159351 ; tmp=r/maxn* 400 +1200 ; r%=maxn; } else { tmp=r/ 1461 * 4 -4712 ; r%= 1461 ; } cout<<d[r]<< " " <<m[r]<< " " ; if (tmp+y[r]> 0 ) cout<<tmp+y[r]; else cout<<( 1 -tmp-y[r])<< " BC" ; cout<< &#x27;
&#x27; ; } return 0 ; } T2 动物园 这道题目我当年在考场看到之后直接就没有去做，没错是的 然后我就光荣爆零了 现在看来，实际上就只是一个位运算的应用，然后题目看起来比较可怕罢了，然后我们的对于这道题 可以用一个数字来记录一下动物的数量，然后需要买的饲料的情况，用二进制就好了 然后我们统计所有的情况，用容斥原理，减去不能怨的动物的数量，剩下的就是还能选的动物的数量啦 注意用一个unsigned long long 和特判 参考代码 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int unsigned long long using namespace std; int n,m,c,k; int ans,dw,ls; signed main () { cin>>n>>m>>c>>k; for ( int i= 1 ;i<=n;i++) { int x; cin>>x; dw|=x; } for ( int i= 1 ;i<=m;i++) { int p,q; cin>>p>>q; ls|= 1ull <<p; } for ( int i= 0 ;i<k;i++) if (!((ls>>i)& 1 )||((dw>>i)& 1 )) ans++; if (ans== 64 &&n== 0 ) cout<< "18446744073709551616" << &#x27;
&#x27; ; //特判 else { if (ans== 64 ) cout<<-n<< &#x27;
&#x27; ; else cout<<( 1ull <<ans)-n<< &#x27;
&#x27; ; } return 0 ; } T3 函数调用 在赛场上我一度认为这道题目是最简单的 但是不是 这道题目看到标签说要用拓扑排序来着 然后拓扑排序一下 实际上对于每个操作进行处理，对于操作2，实际上我们可以看成若干个操作1，然后操作3也可以转化一下，然后我们就可以建一个函数调用关系的有向图，进行拓扑排序，看函数调用的顺序，然后我们对于每一个加法和乘法，看他们对于总的答案的贡献是多少，然后就可做了 参考代码 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # include <queue> using namespace std; const int maxn= 100005 ; const int mod= 998244353 ; int n,m,q; int cnt[maxn]; int a[maxn]; int type[maxn],mul[maxn],add[maxn],pos[maxn]; int out1[maxn],out2[maxn]; vector< int > g1[maxn],g2[maxn]; void topo1 () { queue < int > q; for ( int i= 0 ;i<=m;i++) { out1[i]=g2[i]. size (); if (out1[i]== 0 ) q. push (i); } while (q. size ()) { int x=q. front (); q. pop (); for ( int i= 0 ;i<g1[x]. size ();i++) { int e=g1[x][i]; mul[e]= 1ll *mul[e]*mul[x]%mod; out1[e]--; if (out1[e]== 0 )q. push (e); } } } void topo2 () { queue < int > q; for ( int i= 0 ;i<=m;i++) { out2[i]=g1[i]. size (); if (out2[i]== 0 ) q. push (i); } while (q. size ()) { int x=q. front (); int tag= 1 ; q. pop (); for ( int i=g2[x]. size ();i> 0 ;--i) { int e=g2[x][i -1 ]; cnt[e]=(cnt[e] +1ll *cnt[x]*tag)%mod; tag= 1ll *tag*mul[e]%mod; out2[e]--; if (out2[e]== 0 ) q. push (e); } } } int main () { std::ios:: sync_with_stdio ( false ); cin>>n; for ( int i= 1 ;i<=n;i++) cin>>a[i]; cin>>m; mul[ 0 ]= 1 ; for ( int i= 1 ;i<=m;i++) { cin>>type[i]; if (type[i]== 1 ) { mul[i]= 1 ; cin>>pos[i]>>add[i]; } if (type[i]== 2 ) cin>>mul[i]; if (type[i]== 3 ) { mul[i]= 1 ; int c; cin>>c; for ( int j= 0 ;j<c;++j) { int e; cin>>e; g1[e]. push_back (i); g2[i]. push_back (e); } } } cin>>q; cnt[ 0 ]= 1 ; while (q--) { int x; cin>>x; g1[x]. push_back ( 0 ); g2[ 0 ]. push_back (x); } topo1 (); topo2 (); for ( int i= 1 ;i<=n;i++) a[i]= 1ll *a[i]*mul[ 0 ]%mod; for ( int i= 1 ;i<=m;i++) { if (type[i]== 1 ) a[pos[i]]=(a[pos[i]] +1ll *cnt[i]*add[i])%mod; } for ( int i= 1 ;i<=n;i++) cout<<a[i]<< " " ; return 0 ; } T4 贪吃蛇 讲一个笑话，这是我当初以为整场比赛第二简单的题目 然后我就和这道题目搏斗，与这道题目抗争 最终的结果是我壮烈牺牲 这道题虽然用我的申必贪心方法，样例都能过，但是最后还是爆零了 然后现在看了题解之后，还是有一点懵的 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; const int maxn= 1000005 ; const int inf= 1e9 ; int T,n,a[maxn]; pair < int , int > q1[maxn],q2[maxn]; int l1,r1,l2,r2; pair < int , int > get_max () //取最大蛇 { if (r1==l1) return q2[l2++]; else if (r2==l2) return q1[--r1]; else if (q2[l2]>q1[r1 -1 ]) return q2[l2++]; else return q1[--r1]; } pair < int , int > get_min () //取最小 { if (l1==r1) return q2[--r2]; else if (r2==l2) return q1[l1++]; else if (q2[r2 -1 ]<q1[l1]) return q2[--r2]; else return q1[l1++]; } pair < int , int > Min (pair < int , int > x,pair < int , int > y) { return x<y?x:y; } inline void solve () { l1=r1=l2=r2= 0 ; for ( int i= 1 ;i<=n;++i) q1[r1++]= make_pair (a[i],i); int flag= 0 ,cnt= 0 ,alf= 0 ; while ( 1 ) { cnt++; pair < int , int > x= get_min (),y= get_max (); pair < int , int > z= Min ((l1<r1?q1[l1]: make_pair (inf,-inf)),(l2<r2?q2[r2 -1 ]: make_pair (inf,-inf))); y.first-=x.first; if (y>z||cnt==n -1 ) { if (flag) { cout<<n-(flag-(alf& 1 ))<< &#x27;
&#x27; ; return ; } if (cnt==n -1 ) { cout<< 1 << &#x27;
&#x27; ; return ; } q2[r2++]=y; } else { alf++; if (!flag) flag=cnt; q2[r2++]=y; } } } int main () { cin>>T; T--; cin>>n; for ( int i= 1 ;i<=n;i++) cin>>a[i]; solve (); while (T--) { int k; cin>>k; for ( int i= 1 ;i<=k;i++) { int x; cin>>x; cin>>a[x]; } solve (); } return 0 ; }

【全程NOIP计划】分治与倍增 分治 分治就是分而治之，化整为零的思想 分治的原理是把困难的大问题化解为简单的小问题 然后先解决小问题，然后根据小问题的答案解决大问题 它本质上不是一个算法，而是一个思想 比如快速幂，倍增求lca，归并排序，线段是cdq分治，甚至后缀数组FFT都利用了分治思想 分治虽然不经常出题，但是也非常有用 快速幂 快速幂可以在 O ( l o g b ) O(logb) 的时间复杂度内计算 a b a^b 方法很简单 注意到如果b是偶数，那么就可以先计算 a b 2 a^{ rac{b}{2}} b ​ ,这样问题的规模就减少了一半 如果b是奇数，那么我们就可以计算 a b 2 a^{ rac{b}{2}} b ​ 平方之后再乘a，问题规模同样以不大的代价减少了一般 这里的 a b a^b 就是大问题，而 a b 2 a^{ rac b 2} b ​ 就是小问题了 cpp 抄录 long long f ( long long a, long long b, long long c) { long long temp= f (a,b/ 2 ) if (b& 1 ) return temp*temp%c; else return temp*temp*a%c; } long long ksm ( long long x, long long y, long long z) { long long res= 1 %p; for ( ;y;y>>= 1 ) { if (y& 1 ) res=res*x%z; x=x*x%z; } return res; } 递归实现和迭代实现 实际上都是分治解决的问题，但是方向相反 递归往往是从大问题开始，慢慢递归到小问题，然后进行合并 迭代呢就是要先解决好小问题，从最小的解决，并不断合并得到大问题 从后面的二分和归并排序，还有cdq分治都可以看到这一点 P1045 麦森数 题目 输出 2 p − 1 2^{p-1} 的后五百位数 思路 这里有一个神奇的数学技巧，但是这里用高精度加快速幂就可以了 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # include <cmath> using namespace std; unsigned long long a[ 505 ]={ 1 }; int main () { int p; cin>>p; cout<<( int )(p* log10 ( 2 )) +1 << &#x27;
&#x27; ; for ( ;p> 0 ;p-= 60 ) { unsigned long long f= 0 ; for ( int i= 0 ;i< 500 ;i++) { if (p> 60 ) a[i]<<= 60 ; else a[i]<<=p; a[i]+=f; f=a[i]/ 10 ; a[i]%= 10 ; } } a[ 0 ]-= 1 ; for ( int i= 499 ;i>= 0 ;i--) { cout<<( char )(a[i]+ &#x27;0&#x27; ); if (i% 50 == 0 ) cout<< &#x27;
&#x27; ; } return 0 ; } 快速幂的特别用途 计算模意义下的出发 根据费马小定理 如果模数p为质数，那么a模p意义下的逆元就是 a p − 2 a^{p-2} 也就是说 a ∗ a p − 2 m o d p = 1 a*a^{p-2}mod\space p=1 m o d p = 1 如果给一个数乘以一个 a p − 1 a^{p-1} ,就相当于在模p意义下给这个数除了一个a 在一些计数题目或者期望计算题目中，由于数值可能比较大或者精度比较大，出题人都会让你输出模p意义下的答案 P1850 换教室 思路 这道题目一个期望DP 期望就是数学期望 它的物理意义是，假设一个随机事件执行无穷次，这个随机事件结果的平均值就是期望 公式定义是 ∑ P ( x ) f ( x ) \sum P(x) f(x) ,也就是说吧所有可能出现的值成圣这个值出现的概率，再加起来 那么们就会注意到，事件x发生的概率为 P ( x ) P(x) ，一般来说是一个分数，可能出现的的次数除总次数 那么如果在模质数意义下输出期望，计算 P ( x ) P(x) 的时候最好使用快速木和费马小定理来做除法 P4071 排列计数 题目 求有多少种1到n的排列a，慢慢组序列恰好有m个位置i，使得 a i = i a_i=i ​ = i 答案对 10 9 + 7 10^9+7 + 7 取模 思路 这个题需要先进性一系列的数学推导 我们只需要知道最后的答案一长串 最后用的时候要用快速幂就对了 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int long long using namespace std; const long long maxn= 1000005 ,p= 1e9 +7 ; int T; long long f[maxn]; long long inv[maxn],d[maxn]; inline int read () { int x= 0 ,f= 1 ; char ch= getchar (); while (ch< &#x27;0&#x27; ||ch> &#x27;9&#x27; ){ if (ch== &#x27;-&#x27; ) f= -1 ;ch= getchar ();} while (ch>= &#x27;0&#x27; &&ch<= &#x27;9&#x27; ){x=x* 10 +ch -48 ;ch= getchar ();} return x*f; } long long ksm ( long long a, long long b, long long p) { long long ans= 1 %p; for ( ;b;b>>= 1 ) { if (b& 1 ) ans=( long long )ans*a%p; a=( long long )a*a%p; } return ans; } signed main () { T= read (); f[ 0 ]= 1 ; for ( int i= 1 ;i<maxn;i++) { f[i]=f[i -1 ]*i%p; inv[i]= ksm (f[i],p -2 ,p); //快速幂求逆元 } d[ 1 ]= 0 ,d[ 2 ]= 1 ,d[ 3 ]= 2 ; for ( int i= 4 ;i<maxn;i++) d[i]=(i -1 )*(d[i -1 ]+d[i -2 ])%p; while (T--) { int n= read (),m= read (); if (n==m +1 ) cout<< 0 << &#x27;
&#x27; ; else if (m==n) cout<< 1 << &#x27;
&#x27; ; else if (m== 0 ) cout<<d[n]<< &#x27;
&#x27; ; else cout<<( long long )(f[n]*inv[m]%p*inv[n-m]%p*d[n-m]%p)<< &#x27;
&#x27; ; } return 0 ; } 归并排序 三大基本排序：选择排序，冒泡排序和归并排序 其中的归并排序不仅仅是一个排序的方式，它的分治思想要在其他地方思想 分治排序的方法 首先调用 f ( l , r ) f(l,r) ,然后将l,r划分为两个子问题 [ l , m i d ] 和 [ m i d + 1 , r ] [l,mid]和[mid+1,r] 对于左右两半区间分别排序排好之后，再把两个排好序的区间合并为一个大的有序区间，这个区间合并是比较好做的，因为如果从小向大向大的区间里面填数，那么每次一定从两个小区间的最小端取数，只需要从两个最小值中选取高呢更小的那个，然后放进大区间里面 和快速幂类似，每次分治都会使问题的规模减少至少一半 一次你至多logn次分值之后区间长度就会减少为1 这时子问题就非常容易解决了，长度为1的区间是根本不需要排序的 整个归并排序就是不断把大问题分成小问题，直至小问题非常容易解决为止，再逐步把小问题变成大问题，合并，就非常简单了 代码（求逆序对） cpp 抄录 int cnt= 0 ; int q[ 41000 ]; void f ( int l, int r) { if (l>=r) return ; int mid=(l+r)>> 1 ; f (l,mid), f (mid +1 ,r); int head1=l,head2=mid +1 ; for ( int i=l;i<=r;i++) { if (head2<=r &&(head1>mid||a[head2]<a[head1])) q[i]=a[head2++]; else q[i]=a[head1++],cnt+=(head2-mid -1 ); } for ( int i= 1 ;i<=r;i++) a[i]=q[i]; return ; } 主定理与渐进符号 假设有递归式 T ( n ) = a T ( n / b ) + f ( n ) T(n)=aT(n/b)+f(n) ， f ( n ) f(n) 为递归外的，其中n是问题规模，a是递推子问题数量，n/b是每个子问题的规模 有以下三条 1.若 f ( n ) = O ( n l o g b a − ϵ ) ， ϵ > 0 f(n)=O(n^{log_b^a-\epsilon})，\epsilon>0 a ​ − ϵ ) ， ϵ > 0 那么则 T ( n ) = Θ ( n l o g b a ) T(n)=\Theta(n^{log_b^a}) a ​ ) 2.若 f ( n ) = Θ ( n l o g b a ) f(n)=\Theta(n^{log_b^a}) a ​ ) 那么 T ( n ) = Θ ( n l o g b a l o g n ) T(n)=\Theta(n^{log_b^a}logn) a ​ l o g n ) 3.若 f ( n ) = Ω ( n l o g b a + ϵ ) , ϵ > 0 f(n)=\Omega(n^{log_b^a+\epsilon}),\epsilon>0 a ​ + ϵ ) , ϵ > 0 ,且对于某个常数，C<1和所有充分大的n有 a f ( n b ) ≤ c f ( n ) af( rac n b)\leq cf(n) n ​ ) ≤ c f ( n ) ，那么 T ( n ) = Θ ( f ( n ) ) T(n)=\Theta(f(n)) . 正如上面，有一些符号并不是原来的符号， 因为我打不出来 ， 渐进符号正如其名，随着问题规模n不断增加，计算量h(n)的增加速度不小于f(n)，不大于f(n)，或者几乎和f(n)一样 而并不是说计算量近似等于f(n)，因为当n比较小的时候，可能会出现计算量远远超过f(n)的情况 此外，在渐进符号里面有三种意义不同的符号： O , Θ , Ω O,\Theta ,\Omega 这些都是渐进符号，对于前两个符号，他们经常在复杂度分析中出现 O ( f ( n ) ) O(f(n)) 的就是指问题的复杂度不超过 f ( n ) f(n) ,即O规定了问题的上界 Ω ( f ( n ) ) \Omega(f(n)) 指问题的复杂度不小于 f ( n ) f(n) ，即 Ω \Omega 规定了问题的下界 而当复杂度同时满足 O ( f ( n ) ) O(f(n)) 和 Ω ( f ( n ) ) \Omega(f(n)) 的时候，我们就说问题的复杂度满足 Θ ( f ( n ) ) \Theta(f(n)) 我们再来看一下 主定理 第一条和第三条的 ϵ \epsilon 其实是为了严谨做出出的修正，我们意会的时候可以忽略他们 这样三条定理就可以理解为 1.如果分治外的操作不比 n l o g b a n^{log_b^a} a ​ 多，那么总的复杂度久违 Θ ( n l o g a b ) \Theta (n^{log_a^b}) b ​ ) ,更近一步地，可以理解为如果分治外的操作比分治操作增速更慢，那么分治操作占主要复杂度 2.如果分治外的操作数量级和 n l o g b a n^{log_b^a} a ​ 相当，那么总的复杂度 Θ ( n l o g b a l o g n ) \Theta(n^{log_b^a}logn) a ​ l o g n ) ，这是最常见的情况，如果数量级相当，那么总的复杂度还要乘上一个 l o g n logn 3.如果分治外的操作数量级不比 n l o g b a n^{log_b^a} a ​ 小，那么当n很大的时候，总的复杂度会趋向于 Θ ( f ( n ) ) \Theta(f(n)) ，也就是说，如果分治外的操作非常慢，那么算法就会被这些操作占主导，分治的作用减弱 归并排序的复杂度分析 回到归并排序，首先分治排序的b和a都是2，也就是说问题规模每次减少一半，问题数量每次增加一倍 那么分治外的操作就要和 Θ ( n l o g 2 2 ) \Theta(n^{log_2^2}) 2 ​ ) 也就是 Θ ( n ) \Theta(n) 来相比 显然，把两半序列合并成一个序列，n个元素中的每一个都要访问到 因此，分治外操作的复杂度为 Θ f ( n ) \Theta f(n) 所以根据主定理，归并排序的总复杂度就是 Θ ( n l o g n ) \Theta(nlogn) 的 现在你知道 n l o g n nlogn 的复杂度是怎么来的了 话说，如果是三分归并排序呢？ 速度会更快，但是复杂度并没有变 更快地原因是因为递归层数会降低，但是复杂

【全程NOIP计划】模拟赛#5 A 么么题 题目描述 n n 个人坐成一圈打牌，第 i i 个人开始时手中有 a i a_i ​ 张牌。 从第一个人开始，每个人轮流选择出牌。轮到某个人选择出牌时，他可以选择出一张牌，也可以选择不出牌。不过，如果上一个出牌的人是他自己，或者从来没有人出过牌，那么他就必须选择出牌。然后轮到他的下一个人选择出牌， n n 的下一个人是 1 1 。如果有一个人出完了他所有的牌，游戏结束。 你需要求出，游戏最多能进行多少回合。一个人一次选择叫做一回合。 输入格式 第一行包括一个整数 n n 。 第二行 n n 个整数，第 i i 个表示 a i a_i ​ 。 输出格式 输出一个整数表示答案 输入输出样例 输入 #1 text 抄录 2 2 2 输出 #1 text 抄录 4 输入 #2 text 抄录 11 11 4 5 1 4 1 9 1 9 8 10 输出 #2 text 抄录 563 输入 #3 text 抄录 2 100 1 输出 #3 text 抄录 199 说明/提示 样例一解释： 第一回合 1 1 必须出牌。 第二回合 2 2 选择出牌。 第三回合 1 1 选择不出牌。 第四回合 2 2 必须出牌，他的牌出完了，游戏结束。 共进行了 4 4 回合，容易发现没有回合数更多的方案。 对于前 30 % 30\% 的数据， n = 2 n=2 ， a i ≤ 10 a_i\le 10 ​ ≤ 10 。 对于前 60 % 60\% 的数据， n ≤ 10 n\le 10 ， a i ≤ 10 a_i\le 10 ​ ≤ 10 。 对于前 95 % 95\% 的数据， n ≤ 10 5 n\le 10^5 ， a i ≤ 10 4 a_i\le 10^4 ​ ≤ 1 0 4 。 对于全部数据， 2 ≤ n ≤ 10 5 2\le n\le 10^5 ， 1 ≤ a i ≤ 10 9 1\le a_i\le 10^9 ​ ≤ 1 0 9 。 思路 最优策略下每个人一定都是连续出牌，因为“A 出牌 → 其他人出牌 → A 出牌”一定不如“A 出牌 → 其他人不出 → A 出牌 → 其他人出牌”。而我们又想让不出牌的次数尽可能多，所以最优的方案应该是按 1 , n , n − 1 , n − 2 … 1,n,n-1,n-2\dots 的顺序连续出牌，每个人连续出到剩一张为止，由它前面最近的多余一张牌的人接手，如果没人接手就他自己出完。按照这个思路模拟即可。 当然你也可以接着推式子，但是没必要。推完之后是答案是 n ( s u m − n ) − x + 1 n(sum-n)-x+1 ，其中 x x 是从最后一个出牌的人到 1 1 的距离。标程是式子做法。 如果你挂样例三：注意有 a 2 = 1 a_2=1 ​ = 1 的情况，最后一个出牌的不一定是 2 2 。 如果你挂 #1：你可能没处理好 a 1 = 1 a_1=1 ​ = 1 的情况，应该特判输出 1 1 。 如果你挂 #20：最后一个点是要爆 long long 的，需要用 unsigned long long 输出。 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <string> # include <cstring> using namespace std; int n,a,x; long long s; int main () { cin>>n>>s; if (s== 1 ) { cout<< 1 << &#x27;
