&#x27; ; return 0 ; } B 迷迷题 题目描述 环形 01 串是一种首尾相接的字符串，其中每个字符都是 0 或者 1。 取出环形 01 串中连续的一段称为子串。显然，对于一个长度为 n n ​ 的环形 01 串，它有 n n ​ 个长度为 k k ​ 的子串，其中 k ≤ n k \le n ​。 而长度为 k k 的 01 串共有 2 k 2^k 种。如果对于一个环形 01 串，它有全部 2 k 2^k 种长度为 k k 的子串，那它就是完美的。 请构造出长度尽可能小的、完美的环形 01 串。 输入格式 只有一个整数 k k 输出格式 输出一行你构造出来的环形 01 串。如果有多种方案，输出任意一种即可。 输入输出样例 输入 #1 text 抄录 2 输出 #1 text 抄录 1100 说明/提示 样例解释：这个环形串包含了四个长度为 2 2 的子串： 11 ， 10 ， 00 ， 01 ，因此它是完美的。显然没有更短的方案。 本题共有 20 20 个测试点，其 k k 值分别为 1 1 到 20 20 ，每个测试点满分 5 5 分。本题使用 SPJ 给分，具体方式如下： 如果你构造出的串不是完美的，或者输出格式有误，该测试点得 0 0 分。 假设能构造出的最短的串长度为 a a ，你的答案长度为 b b ，你得到的分数和 b − a b-a 的值有关。 b − a b-a 得分 0 0 5 5 1 ∼ 20 1\sim 20 4 4 21 ∼ 100 21\sim 100 3 3 101 ∼ 10000 101\sim 10000 2 2 10001 ∼ 100000 10001\sim 100000 1 1 ≥ 100000 \ge 100000 ​ 0 0 温馨提示：建议选手赛时自己写一个 checker。 （如果您能一遍过当我没说） 思路 由于 SPJ 的赋分方式，各种乱搞都能拿分，这里不一一介绍。我自己写的随机化乱搞得到了 62 分的好成绩。 前 n n 个字符放 0，状压记录已经出现的长度为 n n 的子串，然后贪心能放 1 就放 1，会出现重复就放 0，这样前 2 n 2^n 个字符就是最短的串。 证明：首先，如果这样一直放，直到放不了了停止，那么串的末尾一定是 n − 1 n-1 个 0，就像这样： 000000111111…………00000[放不了] 这个结论可以反证：假如最后是 000000111111…………XXXXX[放不了] ，那么 XXXXX 一定出现了第三遍，那么 0XXXXX 和 1XXXXX 中至少有一个是重复的，这个串本该在这之前就放不了了。除非 XXXXX 就是最开头的 00000 ，因为这前面没有字符。 于是我们把 000000111111…………00000 最后的 00000 删掉，这就是一个天然形成的环形串，这其中没有重复的子串。那么要证明的就是，每个子串都在这其中出现了。由于我们是贪心放 1，所以只要 ABCDE0 出现， ABCDE1 就一定出现。考虑这前面的字符， 0ABCDE 和 1ABCDE 也都一定出现。换句话说，只要一个末尾是 0 的串出现了，那么去掉末尾这个 0，在开头加上任意字符，得到的串也出现了。 我们发现最开始钦定的 n n 个字符是 0，那么去掉末尾这 n n 个 0，在开头加上 n n 个任意字符……这正是所有长度为 n n 的串！ 欧拉回路也能做，考虑把所有长度为 n − 1 n-1 的串当作点，长度为 n n ​ 的串当作边，本质上就是在原图找一个欧拉回路。 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; int n,x,M; bool a[ 1 << 20 ]; int main () { cin>>n; M=( 1 <<n) -2 ; for ( int i= 0 ;i<( 1 <<n);i++) { x=(x<< 1 )&M; if (a[x| 1 ]) cout<< 0 ; else { cout<< 1 ; x|= 1 ; } a[x]= true ; } return 0 ; } C 喵喵题 题目描述 一个环上有 n n 个点，点分为黑点和白点，初始全是白点。你可以选择任意多次操作，选择这个环上长度为 k k 的连续一段，然后让这一段中所有点颜色翻转，即黑变白，白变黑。环不可以旋转。求能达到多少种不同的状态。由于答案非常大，你只需要输出用二进制表示这个数有多少位数（答案用十进制输出） 输入格式 一行两个整数 n n 和 k k 。 输出格式 一个整数表示答案 输入输出样例 输入 #1 text 抄录 4 2 输出 #1 text 抄录 4 说明/提示 样例解释：容易发现可以达到所有黑点个数为偶数的状态，共 8 8 种。 8 8 用二进制表示为 1000 1000 ，是 4 4 位数。 对于 30 % 30\% 的数据， n ≤ 20 n\le 20 。 对于 60 % 60\% 的数据， n ≤ 1000 n\le 1000 。 对于另外 20 % 20\% 的数据， k = 4 k=4 。 对于全部数据， 1 ≤ k ≤ n ≤ 10 9 1\le k\le n\le 10^9 。 思路 打表找规律数学题。（写暴力打表，大眼观察出结论） 结论：状态数是 2 n − gcd ⁡ ( n , k ) + ( k gcd ⁡ ( n , k ) m o d 2 ) 2^{n - \gcd(n,k) + ( rac{k}{\gcd(n,k)}  mod 2)} k ​ mod 2 ) ，于是答案是 n − gcd ⁡ ( n , k ) + ( k gcd ⁡ ( n , k ) m o d 2 ) + 1 n - \gcd(n,k) + ( rac{k}{\gcd(n,k)}  mod 2) + 1 k ​ mod 2 ) + 1 。 正经证明：由于这本质上是一个 异或线性空间 ，所以状态数一定是 2 2 的 线性基的元素个数 次幂，二进制位数就等于这东西 + 1 +1 。于是 60 60 分给了 bitset 线性基。由于线性空间的性质，线性基的每个元素都可以异或其它的元素而保持线性空间不变，于是把题面换成“可以翻转固定的一段长度为 k k 的段，可以翻转任意距离为 k k 的两点”，答案是相同的。 如果你不知道线性基是啥，也没关系。你只需要明白这个转化是等价的就可以。这个很容易证明：翻转距离为 k k 的两点就是翻转相邻两个连续段，翻转一个连续段就是翻转固定的那个连续段，再用两点把它“移动”到需要的位置。（当然，做完这题之后最好去学习一下： P3812 【模板】线性基 ） 那我们先不考虑那个固定的连续段，只考虑距离为 k k 的两点。发现它其实是 gcd ⁡ ( n , k ) \gcd(n,k) 个相互独立的环，每个环 n gcd ⁡ ( n , k )  rac{n}{\gcd(n,k)} n ​ 个元素，原环上距离为 k k 的两点就等于一个独立环上的相邻两点。由于一个独立环上可以达到的状态是所有偶数个黑点的状态，所以是 2 n gcd ⁡ ( n , k ) − 1 2^{ rac{n}{\gcd(n,k)}-1} n ​ − 1 ， gcd ⁡ ( n , k ) \gcd(n,k) 个环就是 2 n − gcd ⁡ ( n , k ) 2^{n-\gcd(n,k)} 。如果你直接把这个当答案会得到 50 50 分的好成绩。 那么那个固定的连续段到底有没有贡献呢，显然如果它可以被距离为 k k 的两点表示出来就没有贡献。由于它在每个独立环内都是平等的，所以每个独立环内有 k gcd ⁡ ( n , k )  rac{k}{\gcd(n,k)} k ​ 个它的元素，所以只要它是偶数就没有贡献，是奇数就有贡献，有贡献就会让能达到的状态翻倍。 于是就得到了一开始的式子： 2 n − gcd ⁡ ( n , k ) + ( k gcd ⁡ ( n , k ) m o d 2 ) 2^{n - \gcd(n,k) + ( rac{k}{\gcd(n,k)}  mod 2)} k ​ mod 2 ) ​。 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; int n,k; int gcd ( int a, int b) { return b? gcd (b,a%b):a; } int main () { cin>>n>>k; int g= gcd (n,k); cout<<(n-g+(k/g& 1 ) +1 )<< &#x27;
&#x27; ; return 0 ; } D 萌萌题 题目描述 滴叉想要成为管理员，但是要成为管理员，就必须先打败所有的管理员。 有 n n 个管理员，第 i i 个管理员的初始体重是 a i a_i ​ ，还有一个团结度 b i b_i ​ 。由于管理员有时候会休假，所以现在只有前 k k 个管理员在任。滴叉计划在 k k 天之内打败这 k k 名管理员。滴叉每天可以选择一个没被打败过的管理员，如果此时滴叉的体重 大于等于 对方的体重，就可以将对方打败。在第 i i 个管理员被打败之后，其他管理员会团结起来，导致所有管理员的体重都增加了 b i b_i ​ 。滴叉的体重永远不变。 滴叉会以最优策略选择打败管理员的顺序，确保自己能获胜。但是滴叉不知道 k k 的值，所以你需要对于所有 k ∈ [ 1 , n ] k\in [1,n] ，计算出为了打败前 k k 个管理员，滴叉的体重 至少 是多少。 输入格式 第一行输入一个整数 n n 。 接下来 n n 行，每行两个整数，第 i + 1 i+1 行表示 a i a_i ​ 和 b i b_i ​ 。 输出格式 输出 n n 行，第 i i 行对应 k = i k=i 时的答案 输入输出样例 输入 #1 t

【全程NOIP计划】线性优化策略 前缀和，差分序列 前缀和 s i = ∑ 1 i a i s_i=\sum_1^i a_i ​ = 1 ∑ i ​ a i ​ 差分 b i = a i − a i − 1 b_i=a_i-a_{i-1} ​ = a i ​ − a i − 1 ​ 前缀和和差分序列是存在递推关系的 前缀和 cpp 抄录 for ( int i= 1 ;i<=n;i++) s[i]=s[i -1 ]+a[i]; 差分 cpp 抄录 for ( int i= 1 ;i<=n;i++) b[i]=a[i]-a[i -1 ] 由此观之，我们可以发现前缀和和差分存在递推关系 所以前缀和的差分序列等于原序列 s [ i ] − s [ i − 1 ] = s [ i − 1 ] + a [ i ] − s [ i − 1 ] = a [ i ] s[i]-s[i-1] \=s[i-1]+a[i]-s[i-1] \=a[i] 注意局部变量赋初值的问题，要让 s [ 0 ] = 0 s[0]=0 前缀和和差分的用法 前缀和用法有这两个 1.快速区间求和，包括区间异或和区间乘 2.快速做区间加减法 比如，给你一个区间 [ l , r ] [l,r] ，让你给这个区间上面的每一个数加上一个数，或者减去一个数，就可以用前缀和进行优化 快速区间求和我们可以在 O ( 1 ) O(1) 的时间内完成 可以推出来 ∑ l r a i = a l + a l + 1 + a l + 2 + a … + a r = a 1 − r − a i − ( r − 1 ) = s r − s l − 1 \sum_l^ra_i=a_l+a_{l+1}+a_{l+2}+a_{\dots}+a_r \=a_{1-r}-a_{i-(r-1)} \=s_r-s_{l-1} ∑ r ​ a i ​ = a l ​ + a l + 1 ​ + a l + 2 ​ + a … ​ + a r ​ = a 1 − r ​ − a i − ( r − 1 ) ​ = s r ​ − s l − 1 ​ 洛谷P1115 最大字段和 题目 求出一段长度为n的序列a，选出其中连续且非空的一段使得这一段的和最大 思路 1.贪心 我们可以袈裟当前的数为一段的最后一个数，那么无论如何都不可以跳过前一个数去选更前面的数 因为是从左到右扫描序列，因此前一个数为一段结尾的最有答案我们已经求出来了，如果前一段结尾，最优的区间和也不大于零，那么我们加上前面那一段不会更优 如果前一段的区间数大于零，那么可以弄一个更优解 cpp 抄录 int n; int ans= -999 ; int main () { std::ios:: sync_with_stdio ( false ); cin>>n; int sum= 0 ; for ( int i= 1 ;i<=n;i++) { int a; cin>>a; sum+=a; ans= max (ans,sum); if (sum< 0 ) sum= 0 ; } cout<<ans<<endl; return 0 ; } 2.前缀和 如一个区间和可以表示为 s r − s l − 1 s_r-s_{l-1} ​ − s l − 1 ​ ,那么求最大的区间和实际上就是求前面的那个式子，我们可以仿照贪心的思路，固定一个 s r s_r ​ ，那么我们只要求 m i n s l − 1 mins_{l-1} ​ ,这样就可以了 cpp 抄录 int main () { scanf ( "%d" ,&n); for ( int i= 1 ;i<=n;i++) scanf ( "%d,&a[i]); int mn=0,s=0,mx=-200000007; for(int i=1;i<=n;i++) { s+=a[i]; mx=max(mx,s-mn); mn=min(mn,s); } printf(" %d
 ",mx); return 0; } 实际上异或的也可以前缀和，也可以区间异或，主要原因是异或两遍等于没有异或，实际上，只要有累计，即有结合律和逆运算，基本就可以进行前缀和，就是一个类比的思想 乘的逆运算是除，加的逆运算是减，乘法在模意义下的逆运算是乘乘法逆元 注意在不同运算的初始化不同，比如乘法的初值不是0，instead ，是1 除了序列上的前缀和，实际上，还可以在二维平面上做前缀和，我们可以模仿一维前缀和的定义，定义二维前缀和 即 s [ n ] [ m ] = ∑ 1 n ∑ 1 m a [ i ] [ j ] s[n][m]=\sum^n_1 \sum_1^ma[i][j] ∑ n ​ 1 ∑ m ​ a [ i ] [ j ] similarly，我们也可以使用递推加速求前缀和，但是相对于序列的前缀和比较麻烦，主要是因为我们要使用 容斥原理 递推公式为 s [ i ] [ j ] = s [ i − 1 ] [ j ] + s [ i ] [ j − 1 ] + a [ i ] [ j ] − s [ i − 1 ] [ j − 1 ] s[i][j]=s[i-1][j]+s[i][j-1]+a[i][j]-s[i-1][j-1] 这样我们就可以求出来二维前缀和了 然而，我们还可以推出来一个区间的和的公式 对于左上角为(x1,y1),右下角为(x2,y2)的矩形，这个矩形内的区间和为 S = s [ x 2 ] [ y 2 ] − s [ x 1 − 1 ] [ y 2 ] − s [ x 2 ] [ y 1 − 1 ] + s [ x 1 − 1 ] [ y 1 − 1 ] S=s[x2][y2]-s[x1-1][y2]-s[x2][y1-1]+s[x1-1][y1-1] 这样就可以解决很多问题了 P1719 最大加权矩形 题目 给定一个n*n的矩阵，请问其中最大的子矩阵的和为多少？n<=120 思路 直接枚举左上角，再枚举右下角成为一个矩形，直接用二维前缀和暴力就可以了，时间复杂度为 O ( n 4 ) O(n^4) ) ,这里我更加优化了一下 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; int n; int ans,a[ 125 ][ 125 ]; int main () { std::ios:: sync_with_stdio ( false ); cin>>n; for ( int i= 1 ;i<=n;i++) { for ( int j= 1 ;j<=n;j++) { cin>>a[i][j]; a[i][j]+=a[i -1 ][j]; } } for ( int i= 1 ;i<=n;i++) { for ( int k= 1 ;k<=i;k++) { int b[ 150 ]={ 0 }; int f[ 150 ]={ 0 }; for ( int j= 1 ;j<=n;j++) { b[j]=a[i][j]-a[i-k][j]; f[j]= max (f[j -1 ]+b[j],b[j]); ans= max (ans,f[j]); } } } cout<<ans<< &#x27;
&#x27; ; return 0 ; } 不是所有的水都叫农夫山泉，不是只有序列和矩阵能做前缀和 树也是可以做前缀和的 意思是某个节点到根节点的路径上，经过的所有点的权值和 1.如果一个节点减去它的祖先的父亲的前缀和，就得到了这个点到达祖先的链的前缀和 2.如果两个点的前缀和加起来，再减去lca的前缀和，再减去lca的父亲的前缀和，就可以得到两点之间路径的前缀和，妙啊~ 树上的路径跟序列还是有点不一样的，要先减lca再减lca他爸 原理也是容斥原理 另外，如果是边权的前缀和，那么就要减去两次lca前缀和，注意一下点权和边权的前缀和的不同之处 P2420 让我们异或吧 题目 给你一个树，树上有n个节点，每个边有一个权值，给任意两个点，问两点之间路径边权的异或和是多少 思路 实际上，按照之前的思路，要求异或两次lca，但由于lca异或两次等于没有异或，所以两个的前缀和直接异或就可以了（因为是边权的前缀和 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; const int maxn= 100010 ; int n,m; struct edge { int e,next,val; }ed[maxn* 2 ]; int en,first[maxn]; void add_edge ( int s, int e, int val) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; ed[en].val=val; } int s[maxn]; void dfs ( int x, int fa, int w) { s[x]=s[fa]^w; for ( int i=first[x];i;i=ed[i].next) { int e=ed[i].e,w=ed[i].val; if (e!=fa) dfs (e,x,w); } } int main () { cin>>n; for ( int i= 1 ;i<=n -1 ;i++) { int x,y,z; cin>>x>>y>>z; add_edge (x,y,z); add_edge (y,x,z); } dfs ( 1 , 0 ,ed[ 1 ].val); cin>>m; for ( int i= 1 ;i<=m;i++) { int u,v; cin>>u>>v; cout<<(s[u]^s[v])<< &#x27;
&#x27; ; } return 0 ; } 快速区间加 快速区间加是结合前缀和和差分来进行的加速技巧 如果对于差分序列中某一个元素加上一个数字，那么这个加上的数会累计到后面的所有数 因此，我们可以利用这个特性，做一个快速区间加法 就是说对于 b [ i ] + c b[i]+c ,相当于给 a [ i ] a[i] 后面的所有的数都加了一个c 因此我们对于 b [ l ] + c b[l]+c , b [ r + 1 ] − c b[r+1]-c ，这样一前一后相互抵消，这样就能做出来 [ l , r ] [l,r] 的区间加法了 P2367 语文成绩 题目 有一个长度为n的序列，m次操作，对从x到y的元素加z，问最后这个序列n中的最小值 思路 实际上直接利用之前的快速区间加法就可以解决了 非常简单 骚eazy cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; int n,p; int a[ 5000005 ],d[ 5000005 ]; int main () { cin>>n>>p; for ( int i= 1 ;i<=n;i++) { cin>>a[i]; d[i]=a[i]-a[i -1 ]; } for ( int i= 1 ;i<=p;i++) { int x,y,z; cin>>x>>y>>z; d[x]+=z,d[y +1 ]-=z; } int minn= 999999 ; for ( int i= 1 ;i<=n;i++) { a[i]=d[i]+a[i -1 ]; minn= min (a[i],minn); } cout<<minn<<endl; return 0 ; } 离散化 离散化和离散实际上没有什么关系 离散化本质实际上是吧一系列数值用另一系列数值来代替 常见的一个应用就是把大数映射到小数 主要是因为在某些问题中，数值可能会很大，但是有用的数值并不多，因此可以用1—n来表示原来的n个数字，使之大小关系不变，方便进行操作 in fact 我们还可以把实数来映射到整数上，来简化操作 做法 首先识别关键数据，也就是要明确要映射哪些数据 然后将这些数据装到数组b里面，不需要考虑他们的顺序 然后对b排序，这个时候b可能存在重复的数据，然而，这些数据不利于操作，所以还需要进行去重操作，得到没有重复的数组c 如果对于一个关键数据，想要查询它映射之后的id，我们可以用一个二分查找 因为c中的数据各不相同，且保证关键数据一定在c内，因此查找id的二分非常好写 P1496 火烧赤壁 题目 一个白色的数轴，n个指令，每个指令将数轴上的一个区间[ai,bi]染成黑色，当人，某些区间可能被重复染色，但是这跟染一次没有区别，他们仍然是黑色的，现在问你，当指令都执行完毕之后，总共有多少长度的区间被染成黑色 思路 u1s1，让我想到了一个题目 校门外的数 但是这道题目的数据太大了 由于染色的操作数量有限，每次操作有两个端点 因此总共被考虑的端点数只有2n个 存在这样一些子区间，它们之中不包含染色的端点，因此这些子区间要染一起染，可以统一考虑 吧输入涉及到的点叫做关键点，那么就可以给每个关键点一个标号i，同时使用ci表示第i个关键点的坐标，并且保证c数组是单调的 这样ci到ci+1中间的数一定是统一变化的，可以统一考虑，不妨使用di的颜色来表示di到di+1的颜色 这个过程实际上就是离散化的过程，吧关键点较大的坐标映射到了不大的id ps：不知道这样行不行，对于输入的操作的左端点排序，然后比较右端点，处理出来染色的区间长度，直接加减，应该也能算出来 ，实测不行？ 实际上可以。。。 关键代码 cpp 抄录 for ( int i= 1 ;i<=n;i++) { cin>>a[i]>>b[i]; //输入区间端点 d[++dtop]=a[i]; //d为数组实现栈 d[++dtop]=b[i]; } sort (d +1 ,d+top

【解题报告】CSP-S2019 Day1 T1 格雷码 思路 一个模拟出来的搜索，当年我考场上得了个不知道多少分 当年找了个一个小时，结果是错的，也只有60pts cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <string> using namespace std; unsigned long long n,k; void dfs ( unsigned long long n, unsigned long long k) { if (n== 0 ) return ; long long x=( 1 <<(n -1 )); //表示有多少个 if (k== 0 ) //如果k为0的话，没有好吧 { for ( long long i= 1 ;i<=n;i++) cout<< "0" ; return ; } if (k +1 >x) //如果要的数字在中间的右边 { long long next= 2 *x-k -1 ; //计算对应右边的n-1位格雷码 cout<< "1" ; dfs (n -1 ,next); } else //在左边就是正常的格雷码 { long long next=k; cout<< "0" ; dfs (n -1 ,next); } } int main () { //freopen("code.in","r",stdin); //freopen("code.out","w",stdout); cin>>n>>k; dfs (n,k); cout<<endl; // fclose(stdin); // fclose(stdout); return 0 ; } 然后我们考虑对的思路 我们手算出前几个格雷码，然后可以找到规律 我们就能进行一些操作了 毕竟，像这种输入一个或者两个数字然后输出一个数字的 要么就是有一个简单的递推式 要么就能打表找规律 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <string> # include <cstring> using namespace std; int n; unsigned long long k; int main () { cin>>n>>k; k^=k>> 1 ; while (~--n) cout<<(k>>n& 1 ); return 0 ; } T2 括号树 思路 直接一个不用思考的暴力，可以有20pts cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; const int maxn= 500005 ; int n,fa[maxn],ans; bool flag= true ; char s[maxn]; struct edge { int e,next; }ed[maxn<< 1 ]; int en,first[maxn]; void add_edge ( int s, int e) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; } bool check ( int l, int r) { int cnt= 0 ; for ( int i=l;i<=r;i++) { if (s[i]== &#x27;(&#x27; ) cnt++; else if (s[i]== &#x27;)&#x27; ) cnt--; if (cnt< 0 ) return false ; } if (cnt== 0 ) return true ; return false ; } int main () { cin>>n; scanf ( "%s" ,s +1 ); for ( int i= 1 ;i<=n -1 ;i++) { int x; cin>>x; fa[i +1 ]=x; if (fa[i +1 ]!=i) flag= false ; add_edge (i +1 ,x); add_edge (x,i +1 ); } if (flag) { for ( int i= 1 ;i<=n;i++) { int cnt= 0 ; for ( int l= 1 ;l<=i;l++) { for ( int r=l +1 ;r<=i;r++) { if ( check (l,r)) cnt++; } } ans=(ans^(cnt*i)); } cout<<ans<< &#x27;
&#x27; ; return 0 ; } return 0 ; } 然后我们手推一下，到每个位置，一共有多少对括号 一定要手推！！！ 不然是找不到规律的 然后我们发现 一个后括号如果能匹配一个前括号， 假设这个前括号的前1位同样有一个已经匹配了的后括号，那么我们势必可以把当前的匹配和之前的匹配序列合并，当前的这个后括号的贡献值，其实就等于前面那个后括号的贡献值+1！ 也就是这么一个性质，可以拿到55pts的高分 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int long long using namespace std; const int maxn= 500005 ; int n,fa[maxn],ans; int st[maxn],don[maxn],sum[maxn],size; bool flag= true ; char s[maxn]; struct edge { int e,next; }ed[maxn<< 1 ]; int en,first[maxn]; void add_edge ( int s, int e) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; } bool check ( int l, int r) { int cnt= 0 ; for ( int i=l;i<=r;i++) { if (s[i]== &#x27;(&#x27; ) cnt++; else if (s[i]== &#x27;)&#x27; ) cnt--; if (cnt< 0 ) return false ; } if (cnt== 0 ) return true ; return false ; } signed main () { cin>>n; scanf ( "%s" ,s +1 ); for ( int i= 1 ;i<=n -1 ;i++) { int x; cin>>x; fa[i +1 ]=x; if (fa[i +1 ]!=i) flag= false ; add_edge (i +1 ,x); add_edge (x,i +1 ); } if (flag) { for ( int i= 1 ;i<=n;i++) { if (s[i]== &#x27;)&#x27; ) { if (size== 0 ) continue ; int t=st[size]; don[i]=don[t -1 ] +1 ; size--; } else if (s[i]== &#x27;(&#x27; ) st[++size]=i; } for ( int i= 1 ;i<=n;i++) sum[i]=sum[i -1 ]+don[i]; for ( int i= 1 ;i<=n;i++) ans=(ans^(i*sum[i])); cout<<ans<< &#x27;
&#x27; ; return 0 ; } return 0 ; } 然后我们发现 树上一个点到根的距离实际上也对应一个序列 我们可以对应每个点来计算，看他之前的括号排序是什么样子的 因为我们递归的时候有回溯 所以所有的答案不影响 所以实际上就是一个序列问题转化为树上问题 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int long long using namespace std; const int maxn= 500005 ; int n,fa[maxn],ans; int st[maxn],don[maxn],sum[maxn],size; bool flag= true ; char s[maxn]; struct edge { int e,next; }ed[maxn<< 1 ]; int en,first[maxn]; void add_edge ( int s, int e) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; } void dfs ( int x) { int tmp= 0 ; if (s[x]== &#x27;)&#x27; ) { if (size!= 0 ) { tmp=st[size]; don[x]=don[fa[tmp]] +1 ; size--; } } else if (s[x]== &#x27;(&#x27; ) st[++size]=x; sum[x]=sum[fa[x]]+don[x]; for ( int i=first[x];i;i=ed[i].next) { int e=ed[i].e; dfs (e); } if (tmp!= 0 ) st[++size]=tmp; else if (size) size--; } bool check ( int l, int r) { int cnt= 0 ; for ( int i=l;i<=r;i++) { if (s[i]== &#x27;(&#x27; ) cnt++; else if (s[i]== &#x27;)&#x27; ) cnt--; if (cnt< 0 ) return false ; } if (cnt== 0 ) return true ; return false ; } signed main () { cin>>n; scanf ( "%s" ,s +1 ); for ( int i= 2 ;i<=n;i++) { int x; cin>>x; add_edge (x,i); fa[i]=x; } dfs ( 1 ); for ( int i= 1 ;i<=n;i++) ans=(ans^(i*sum[i])); cout<<ans<< &#x27;
&#x27; ; return 0 ; } T3 树上的数 思路 这道题目具有里程碑意义 自从这道黑题之后，提高级的比赛在出黑题的时代大潮中一去不复返 直到现在还有深远的影响力，对一代又一代OIer留下了深刻印象 然而我还是不会 所以我们看一下 我们这道题目分部分分来进行研究 感谢@ lyyi2003 菊花图 菊花图的话有一个花心和一堆花瓣 然后我们根据手模可以发现 可以按照结点的编号和数字进行贪心 当我们处理一个点的时候，对于一个数字，枚举跟它相连的点 如果这个相邻的点没有被访问过，并且这个点是最后一个数字或者和之前这个数字并没有产生过直接联系 我们就以这个数字为排列的下一个数字 可以得到25pts cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # include <cmath> using namespace std; const int maxn= 4005 ; int p[maxn],ans[maxn]; bool vis[maxn]; int fa[maxn]; int get ( int x) { return fa[x]=(x==fa[x]? x: get (fa[x])); } int main () { int n,T; cin>>T; while (T--) { memset (vis, false , sizeof (vis)); cin>>n; for ( int i= 1 ;i<=n;i++) fa[i]=i; for ( int i= 1 ;i<=n;i++) cin>>p[i]; int x,y; for ( int i= 1 ;i<n;i++) cin>>x>>y; for ( int i= 1 ;i<=n;i++) { int x=p[i]; for ( int j= 1 ;j<=n;j++) { if (!vis[j]&&(i==n|| get (x)!= get (j))) { ans[i]=j; fa[ get (x)]= get (j); vis[j]= true ; break ; } } } for ( int i= 1 ;i<=n;i++) cout<<ans[i]<< " " ; cout<< &#x27;
&#x27; ; } return 0 ; } 我们发现可以用拓扑序的模型来贪心 怎么贪呢 我们为每条边规定一个优先级，如果一条边的优先级大于另一条边的话，那么这条边必须造另一条边的后面删除 所以我们按照这个思路贪心，每次选一个当前数字能到达的，不和之前的条件冲突的，标号最小的结点作为这个数字最终所在的结点，然后将这个条件加入 这个怎么做呢，我们可以用一堆方法标记一下一条边和左右两条边的优先级，然后每次从当前数字开始找左右两边符合条件的点，然后把新条件对应的标记值更新就好了 然后我们继续考虑正解 我们按照上面的思路继续思考 我们发现，只有与同一个节点相邻的边之间才会有优先级的问

