【解题报告】洛谷P5658 括号树 题目链接 https://www.luogu.com.cn/problem/P5658 思路 看到这道题目，我们有必要了解一下括号序列 然后不会打正解？ 好，打部分分 f i = i − 1 f_i=i-1 ​ = i − 1 的部分 n ≤ 200 n \le 200 这一部分的分数我们可以直接打暴力，然后三个循环 O ( n 3 ) O(n^3) ) 再加上一个 O ( n ) O(n) 的判断被嵌套在这三个循环里面，总共是 O ( n 4 ) O(n^4) ) ，可以过掉这一部分的数据 期望得分 20pts cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> using namespace std; const int maxn= 500005 ; int n,fa[maxn],ans; bool flag= true ; char s[maxn]; struct edge { int e,next; }ed[maxn<< 1 ]; int en,first[maxn]; void add_edge ( int s, int e) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; } bool check ( int l, int r) { int cnt= 0 ; for ( int i=l;i<=r;i++) { if (s[i]== &#x27;(&#x27; ) cnt++; else if (s[i]== &#x27;)&#x27; ) cnt--; if (cnt< 0 ) return false ; } if (cnt== 0 ) return true ; return false ; } int main () { cin>>n; scanf ( "%s" ,s +1 ); for ( int i= 1 ;i<=n -1 ;i++) { int x; cin>>x; fa[i +1 ]=x; if (fa[i +1 ]!=i) flag= false ; add_edge (i +1 ,x); add_edge (x,i +1 ); } if (flag) { for ( int i= 1 ;i<=n;i++) { int cnt= 0 ; for ( int l= 1 ;l<=i;l++) { for ( int r=l +1 ;r<=i;r++) { if ( check (l,r)) cnt++; } } ans=(ans^(cnt*i)); } cout<<ans<< &#x27;
&#x27; ; return 0 ; } return 0 ; } n ≤ 10 5 n \le 10^5 的部分 我们可以发现，实际上我们的瓶颈在于我们有一个 n 3 n^3 的美剧左端点，枚举右端点和一次判断，我们要完成 10 5 10^5 的数据，至少要达到 O ( n l o g n ) O(nlogn) 的时间复杂度，所以我们要继续优化 根据大佬的提示，我们可以知道下面一段话 我们发现，一个后括号如果能匹配一个前括号， 假设这个前括号的前1位同样有一个已经匹配了的后括号，那么我们势必可以把当前的匹配和之前的匹配序列合并，当前的这个后括号的贡献值，其实就等于前面那个后括号的贡献值+1！ 然后我们就可以按照这个写出代码，这个结论要用手模一下 期望得分 55pts cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int long long using namespace std; const int maxn= 500005 ; int n,fa[maxn],ans; int st[maxn],don[maxn],sum[maxn],size; bool flag= true ; char s[maxn]; struct edge { int e,next; }ed[maxn<< 1 ]; int en,first[maxn]; void add_edge ( int s, int e) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; } bool check ( int l, int r) { int cnt= 0 ; for ( int i=l;i<=r;i++) { if (s[i]== &#x27;(&#x27; ) cnt++; else if (s[i]== &#x27;)&#x27; ) cnt--; if (cnt< 0 ) return false ; } if (cnt== 0 ) return true ; return false ; } signed main () { cin>>n; scanf ( "%s" ,s +1 ); for ( int i= 1 ;i<=n -1 ;i++) { int x; cin>>x; fa[i +1 ]=x; if (fa[i +1 ]!=i) flag= false ; add_edge (i +1 ,x); add_edge (x,i +1 ); } if (flag) { for ( int i= 1 ;i<=n;i++) { if (s[i]== &#x27;)&#x27; ) { if (size== 0 ) continue ; int t=st[size]; don[i]=don[t -1 ] +1 ; size--; } else if (s[i]== &#x27;(&#x27; ) st[++size]=i; } for ( int i= 1 ;i<=n;i++) sum[i]=sum[i -1 ]+don[i]; for ( int i= 1 ;i<=n;i++) ans=(ans^(i*sum[i])); cout<<ans<< &#x27;
&#x27; ; return 0 ; } return 0 ; } 无特殊性质 这种情况，我们要做的是把序列上的问题转化到树上，每个结点到根的简单路径有且仅有一条，所以如果单单是对于这一条链的话，策略跟上面一样,但是我们的前一个结点就变了，上一个左括号的，也就是上面的代码中的 t t 我们要改成 f a [ t ] fa[t] 这样，然后计算每个结点对应的合法序列的个数也要改变 那我们压进栈里面的数字怎么办啊 我们设置了一个中间值，记录上一个左括号的位置，如果这个中间值为 0 0 的话，说明这是一个左括号，那么在栈里面加入它，如果不是 0 0 的话，判断一下栈的大小是否为 0 0 ，如果不是 0 0 的话，我们就可以发现一个事情，在之前的递归中，我们一定压入了一个数，但是这个数会影响后面的答案，所以我们将这个值弹出，相当于回溯一下子 期望得分100pts cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # define int long long using namespace std; const int maxn= 500005 ; int n,fa[maxn],ans; int st[maxn],don[maxn],sum[maxn],size; bool flag= true ; char s[maxn]; struct edge { int e,next; }ed[maxn<< 1 ]; int en,first[maxn]; void add_edge ( int s, int e) { en++; ed[en].next=first[s]; first[s]=en; ed[en].e=e; } void dfs ( int x) { int tmp= 0 ; if (s[x]== &#x27;)&#x27; ) { if (size!= 0 ) { tmp=st[size]; don[x]=don[fa[tmp]] +1 ; size--; } } else if (s[x]== &#x27;(&#x27; ) st[++size]=x; sum[x]=sum[fa[x]]+don[x]; for ( int i=first[x];i;i=ed[i].next) { int e=ed[i].e; dfs (e); } if (tmp!= 0 ) st[++size]=tmp; else if (size) size--; } bool check ( int l, int r) { int cnt= 0 ; for ( int i=l;i<=r;i++) { if (s[i]== &#x27;(&#x27; ) cnt++; else if (s[i]== &#x27;)&#x27; ) cnt--; if (cnt< 0 ) return false ; } if (cnt== 0 ) return true ; return false ; } signed main () { cin>>n; scanf ( "%s" ,s +1 ); for ( int i= 2 ;i<=n;i++) { int x; cin>>x; add_edge (x,i); fa[i]=x; } dfs ( 1 ); for ( int i= 1 ;i<=n;i++) ans=(ans^(i*sum[i])); cout<<ans<< &#x27;
&#x27; ; return 0 ; }

【解题报告】洛谷P6852 Mex 题目链接 https://www.luogu.com.cn/problem/P6852 思路 要求构造一个序列 我们发现，对于一个区间 [ l , r ] [l,r] 的 m e x mex 为 v a l val ， [ 0 , v a l − 1 ] [0,val-1] 必须都出现在这个区间中，并且 v a l val 不能出现在这个区间中 所以我们对于某个值 v a l = 0 val=0 可以变成这个 v a l val 必须出现的 一个区间，和不能出现的很多区间 v a l ≠ 0 val 
ot =0 = 0 可以变成一个必须出现的区间和不能出现的区间，实际上就是把不能出现的区间并起来，剩下的就是能出现的区间了 所以我们从小到大填入一个数字 v a l val ,每次在 v a l val 必须出现的区间中随便选一个点填进去 然后我们用一个集合来维护可以选择的点，每次用二分确定还能选择符合要求的数字，且必须在区间的左端点，然后再判断它是不是在不能出现的区间里面，如果不在的话，填进去，否则不填进去，然后找不在这个区间只能的能填进去的下一个位置，然后重复上述步骤即可 我们特判一下 0 0 的位置，然后就解决了 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # include <set> using namespace std; const int maxn= 500005 ; int n,m; int loc[maxn],roc[maxn]; int lb[maxn],rb[maxn]; int pre[maxn],ans[maxn]; bool flag; set < int > s; int main () { cin>>n>>m; for ( int i= 0 ;i<=n;i++) s. insert (i); for ( int i= 0 ;i<=n +1 ;i++) { loc[i]= 0 ,roc[i]=n; lb[i]=n +1 ,rb[i]= -1 ; } for ( int i= 1 ;i<=m;i++) { int x,y,val; cin>>x>>y>>val; if (val) { loc[val -1 ]= max (loc[val -1 ],x); roc[val -1 ]= min (roc[val -1 ],y); lb[val]= min (lb[val],x),rb[val]= max (rb[val],y); } else { pre[x]++; pre[y +1 ]--; } } for ( int i=n;i>= 0 ;i--) { loc[i]= max (loc[i],loc[i +1 ]); roc[i]= min (roc[i],roc[i +1 ]); } for ( int i= 0 ;i<=n;i++) { pre[i]+=pre[i -1 ]; if (loc[ 0 ]<=i&&i<=roc[ 0 ]&&pre[i]== 0 ) { ans[i]= 0 ; s. erase (i); break ; } } for ( int i= 1 ;i<=n;i++) { set < int >::iterator it=s. lower_bound (loc[i]); if (it!=s. end ()&&*it<=roc[i]&&(lb[i]>*it||*it>rb[i])) { ans[*it]=i; s. erase (it); } else if (rb[i]!= -1 ) { it=s. lower_bound (rb[i] +1 ); if (it!=s. end ()&&*it<=roc[i]) { ans[*it]=i; s. erase (it); } } } if (s. size ()) cout<< -1 << &#x27;
&#x27; ; else { for ( int i= 0 ;i<=n;i++) cout<<ans[i]<< " " ; cout<< &#x27;
&#x27; ; } return 0 ; }

【解题报告】洛谷P1168 中位数 题目链接 https://www.luogu.com.cn/problem/P1168 思路 这道题目是个数据结构 由于数据结构很长时间没有码了，所以就开了一个这个 发现不怎么有思路 本来想开一个数组，然后比较位置，然后加入数组的，发现炸掉 然后主流的思路有以下两种，我也基本搞懂了 STL大法 stl大法好！ 用一个vector,然后直接查询就好了 然后vector我似乎不太会用，所以我就查了一下下百度 void push_back(const T& x):向量尾部增加一个元素X iterator insert(iterator it,const T& x):向量中迭代器指向元素前增加一个元素x iterator insert(iterator it,int n,const T& x):向量中迭代器指向元素前增加n个相同的元素x iterator insert(iterator it,const_iterator first,const_iterator last):向量中迭代器指向元素前插入另一个相同类型向量的[first,last)间的数据 —— https://www.cnblogs.com/zsq1993/p/5929806.html 这里可以直接使用第二个用法，然后加上一个 upper_bound() 就行了 话说我第一次知道有这种用法 如果数据是单调递减会不会炸掉啊 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # include <vector> using namespace std; const int maxn= 100005 ; int n; vector < int > a; int main () { cin>>n; for ( int i= 1 ;i<=n;i++) { int x; cin>>x; a. insert ( upper_bound (a. begin (),a. end (),x),x); if (i& 1 ) cout<<a[(i -1 )/ 2 ]<< &#x27;
&#x27; ; } return 0 ; 对顶堆 还是用到了stl 但是思想完全不一样 我们建一个大根堆，建一个小根堆 然后就完了 原图已丢失 左边是一个大根堆，堆顶靠近mid，右边是一个小根堆，堆顶靠近mid 每次查询的时候调整堆的大小，是两个堆的大小相差为1，多的那个第一个就是中位数，速度会比用vector的更快一些 cpp 抄录 # include <iostream> # include <cstdio> # include <algorithm> # include <cstring> # include <string> # include <vector> # include <queue> using namespace std; const int maxn= 100005 ; int n; int a[maxn]; int jdz ( int x) { return x> 0 ? x:-x; } priority_queue < int ,vector< int >,less< int > > q1; //大根堆 priority_queue < int ,vector< int >,greater< int > > q2; //小根堆 int main () { cin>>n; cin>>a[ 1 ]; int mid=a[ 1 ]; cout<<mid<< &#x27;
&#x27; ; for ( int i= 2 ;i<=n;i++) { cin>>a[i]; if (a[i]>mid) q 2. push (a[i]); else q 1. push (a[i]); if (i& 1 ) { while (q 1. size ()!=q 2. size ()) { if (q 1. size ()>q 2. size ()) { q 2. push (mid); mid=q 1. top (); q 1. pop (); } else { q 1. push (mid); mid=q 2. top (); q 2. pop (); } } cout<<mid<< &#x27;
&#x27; ; } } return 0 ; }
